[
  {
    "id": "ascii-only-codec-on-corpus-values",
    "severity": "blocking",
    "since": "2026-09-01",
    "failureMessage": "hitbut's ids and text are Hebrew, and JS `btoa`/`atob` throw or mangle anything outside Latin1 — a raw call crashes on real data",
    "fix": "encode/decode the value as UTF-8 bytes first, or reuse the base64url cursor codec already in src/backend/corpus/store.ts",
    "scanFiles": "/^src\\/.*\\.tsx?$/",
    "excludeFiles": "src/backend/corpus/store.ts",
    "matchLines": [
      {
        "match": "/\\bbtoa\\(|\\batob\\(/",
        "what": "calls {match} directly, unsafe on the Hebrew ids and text this corpus stores"
      }
    ]
  }
]

// hitbut — this repo's own rules: the ones that are true here and portable nowhere.
// Seeded empty at adoption; everything in it is this repo's to write. A lesson that
// would hold in another repo belongs in a canon pack instead — propose it upstream.
export default {
  id: 'hitbut',
  version: 1,
  ruleRoutingGuidance: {
    belongs: 'working rules and lessons specific to this repository and not portable to any other',
    excludes: 'anything true beyond this repo — that belongs in a canon pack, proposed upstream',
  },
  detect: null,
  marker: null,
  prose: 'RULES.md',
  worldRules: [],
};

